const fs=require('fs'),path=require('path'),cp=require('child_process'),crypto=require('crypto');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/pages/configuracoes.css',FOUNDATION='assets/css/pages/configuracoes-foundation.css',PAGE='configuracoes.html';
const SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,WIDTHS=[360,390,430,759,760,761,1024,1179,1180,1181,1280,1440];
const sh=c=>cp.execSync(c,{encoding:'utf8'}).trim(),assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,n=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:n(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:n([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=n(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=n(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v);}return out;}
function verifyReach(){const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),tracked=new Set(cp.execFileSync('git',['ls-files','-z','assets/css'],{encoding:'utf8'}).split('\0').filter(f=>f.endsWith('.css')));assert(importsFor(FOUNDATION,tracked).includes(TARGET),'foundation import drift');const html=fs.readFileSync(PAGE,'utf8');assert((html.match(/assets\/css\/pages\/configuracoes-foundation\.css\?v=/g)||[]).length===1,'foundation link drift');const pages=[];for(const p of report.pageAssets){const seen=new Set(),stack=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(stack.length){const f=stack.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break;}for(const n of importsFor(f,tracked))stack.push(n);}if(hit)pages.push(p.page);}assert(JSON.stringify(pages.sort())===JSON.stringify([PAGE]),'reach pages '+JSON.stringify(pages));console.log(`REACH AUTHORITY PASS|chain=${PAGE}->${FOUNDATION}->${TARGET}|pages=1`);}
function verify(p){assert(p.declarations.length===734,'decl '+p.declarations.length);assert(p.dead.length===53,'dead '+p.dead.length);assert(new Set(p.dead.map(d=>d.selector)).size===18,'selectors drift');const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===11,'identical '+identical);assert(p.dead.every(d=>!d.important&&!d.winnerImportant),'important drift');const contexts=[...new Set(p.dead.map(d=>d.context))].sort(),expected=['','@media (max-width: 760px)','@media (max-width: 1180px)'].sort();assert(JSON.stringify(contexts)===JSON.stringify(expected),'contexts '+JSON.stringify(contexts));console.log('DEAD ROWS PASS|decl=734|dead=53|selectors=18|identical=11|changed=42|contexts=3');}
function specsFor(p){const m=new Map();for(const d of p.dead){if(!m.has(d.selector))m.set(d.selector,new Set());m.get(d.selector).add(d.property);}return[...m].map(([selector,props])=>({selector,props:[...props].sort()}));}
async function capture(browser,tag,specs){const snapshots={},seen=new Map(specs.map(s=>[s.selector,0]));for(const width of WIDTHS){const ctx=await browser.newContext({viewport:{width,height:1100},reducedMotion:'reduce'}),p=await ctx.newPage();await p.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort();});await p.goto(`http://127.0.0.1:4173/${PAGE}?${tag}-${width}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:20000});await p.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.removeAttribute('data-auth-guard');document.documentElement.classList.remove('doke-mobile-shell-pending');document.querySelectorAll('[data-settings-hydration-ready]').forEach(el=>{el.hidden=false;el.removeAttribute('aria-hidden');});const root=document.querySelector('[data-state-boundary="configuracoes"]');if(root){root.setAttribute('data-view-state','ready');root.setAttribute('aria-busy','false');}});await p.waitForTimeout(120);const snap=await p.evaluate(specs=>{const round=n=>Math.round(n*1000)/1000,rows={};for(const spec of specs){const nodes=[...document.querySelectorAll(spec.selector)];rows[spec.selector]=nodes.slice(0,8).map((el,index)=>{const cs=getComputedStyle(el),r=el.getBoundingClientRect(),props={};for(const k of spec.props)props[k]=cs.getPropertyValue(k).trim();return{index,tag:el.tagName,className:String(el.className||''),props,rect:[round(r.x),round(r.y),round(r.width),round(r.height)]};});rows[spec.selector+'::__count']=nodes.length;}return{rows,media:{max760:matchMedia('(max-width: 760px)').matches,max1180:matchMedia('(max-width: 1180px)').matches},doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,bodyClientWidth:document.body.clientWidth,bodyScrollWidth:document.body.scrollWidth,scrollHeight:document.documentElement.scrollHeight}}},specs);for(const spec of specs)seen.set(spec.selector,seen.get(spec.selector)+snap.rows[spec.selector+'::__count']);assert(snap.doc.scrollWidth<=snap.doc.clientWidth,'overflow '+tag+' '+width);snapshots[width]=snap;await ctx.close();}const absent=[...seen].filter(([,count])=>count===0).map(([sel])=>sel),present=seen.size-absent.length;assert(present===18&&absent.length===0,`DOM coverage ${present}/${absent.length}`);console.log(`REAL DOM COVERAGE|tag=${tag}|presentSelectors=${present}|absentSelectors=0|absent=-`);return{snapshots,coverage:{present,absent}};}
function apply(p){const src=fs.readFileSync(TARGET,'utf8'),had=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(had&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(d.property+':'),'line mismatch '+d.line);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n')+(had?'\n':''));const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='53'&&stat[2]===TARGET,'delta '+stat.join('/'));const after=parse(fs.readFileSync(TARGET,'utf8'));assert(after.declarations.length===681&&after.dead.length===0,`after ${after.declarations.length}/${after.dead.length}`);return after;}
(async()=>{assert(SHA&&BLOB,'missing env');assert(sh('git rev-parse HEAD')===SHA,'wrong sha');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');verifyReach();const src=fs.readFileSync(TARGET,'utf8'),beforeBytes=Buffer.byteLength(src),parsed=parse(src);assert(beforeBytes===42219,'before bytes '+beforeBytes);verify(parsed);const specs=specsFor(parsed),server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const before=await capture(browser,'before',specs);apply(parsed);const buf=fs.readFileSync(TARGET),afterBytes=Buffer.byteLength(buf),hash=crypto.createHash('sha256').update(buf).digest('hex'),after=await capture(browser,'after',specs);await browser.close();assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');assert(sh('git diff --name-only -- assets')===TARGET,'scope drift');console.log(`CANDIDATE BUILD PASS|hash=${hash}|bytes=${beforeBytes}->${afterBytes}|files=1|additions=0|deletions=53|decl=734->681|dead=53->0`);console.log(`CANDIDATE RUNTIME PASS|viewports=${WIDTHS.join(',')}|runtimeDiffs=0|overflow=0|boundaries=760/1180|selectors=18|domPresent=${before.coverage.present}|domAbsent=0|staticCascadeRows=53|page=${PAGE}`);fs.writeFileSync('/tmp/ux-css-debt-034-candidate-hash',hash+'\n');fs.writeFileSync('/tmp/ux-css-debt-034-candidate-bytes',String(afterBytes)+'\n');}finally{server.kill('SIGTERM');}})().catch(e=>{console.error(e.stack||e);process.exit(1)});